struct Base {
    Base() { init(); }           // runs Base::init
    virtual void init() {}
    virtual void run(int) {}
    virtual ~Base() = default;
};
struct Derived : Base {
    void init() override {}      // not called from Base()
    void run(long) override {}   // doesn't override!
};
